<?php
declare(strict_types=1);
function notifications_for_user(mysqli $conn,int $userId,int $limit=50):array{$limit=max(1,min(100,$limit));$s=$conn->prepare("SELECT id,event_type,title,message,entity_type,entity_id,read_at,created_at,version FROM notifications WHERE user_id=? ORDER BY created_at DESC,id DESC LIMIT {$limit}");$s->bind_param('i',$userId);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();return array_map(static fn(array $row):array=>['id'=>(int)$row['id'],'eventType'=>(string)$row['event_type'],'title'=>(string)$row['title'],'message'=>(string)$row['message'],'entityType'=>$row['entity_type']===null?null:(string)$row['entity_type'],'entityId'=>$row['entity_id']===null?null:(int)$row['entity_id'],'readAt'=>$row['read_at']===null?null:(string)$row['read_at'],'createdAt'=>(string)$row['created_at'],'version'=>(int)$row['version']],$rows);}
function notification_repository_one(mysqli $conn,int $userId,int $notificationId,bool $forUpdate=false):array{$sql='SELECT * FROM notifications WHERE id=? AND user_id=? LIMIT 1';if($forUpdate)$sql.=' FOR UPDATE';$s=$conn->prepare($sql);$s->bind_param('ii',$notificationId,$userId);$s->execute();$row=$s->get_result()->fetch_assoc()?:[];$s->close();return$row;}
